insert into public.products (slug, title, title_he, category, color, price, compare_at_price, badge, short, description, details, image_path) values
  ('am-tee-black', 'AM TEE — BLACK', 'חולצת טי שחורה', 'tees', 'שחור', 179, NULL, 'קולקציית הפתיחה', 'טי כותנה כבדה בגזרה נקייה, עם הלוגו רקום בזהב על החזה.', 'החולצה שפותחת את הקולקציה. כותנה מסורקת כבדה שנופלת ישר ולא מתעוותת בכביסה, גזרה נקייה שאינה צמודה ואינה אוברסייז, והלוגו של AM ברקמת זהב על החזה השמאלי. שחור עמוק שנשאר שחור.', '["100% כותנה מסורקת, 240 גרם למ״ר", "רקמת זהב על החזה השמאלי", "צווארון ריב מחוזק שלא נמתח", "תפר כתף לכתף", "כביסת מכונה 30 מעלות, הפוך"]'::jsonb, '/store/images/am-tee-black.jpg'),
  ('am-tee-white', 'AM TEE — WHITE', 'חולצת טי לבנה', 'tees', 'לבן', 179, NULL, 'קולקציית הפתיחה', 'אותה גזרה בלבן שמנת, עם הלוגו בזהב שמבליט את הניגוד.', 'הגרסה הלבנה של הטי. אותה כותנה כבדה ואותה גזרה, בגוון לבן נקי שנותן לזהב לעבוד הכי חזק. הבד אטום מספיק כדי שלא יהיה שקוף, גם בלבן.', '["100% כותנה מסורקת, 240 גרם למ״ר", "רקמת זהב על החזה השמאלי", "צווארון ריב מחוזק שלא נמתח", "בד אטום, לא שקוף", "כביסת מכונה 30 מעלות, הפוך"]'::jsonb, '/store/images/am-tee-white.jpg'),
  ('am-shorts-black', 'AM SHORTS — BLACK', 'מכנסי פוטר שחורים', 'shorts', 'שחור', 229, NULL, NULL, 'מכנסי פוטר קצרים עם שרוך זהב וכיסים צדדיים.', 'פוטר מוברש מבפנים, גזרה ישרה שנעצרת מעל הברך, גומי במותן עם שרוך וקצוות זהב. שני כיסים צדדיים עמוקים שבאמת מחזיקים טלפון. הלוגו רקום בזהב על הרגל השמאלית.', '["פוטר 80% כותנה, 20% פוליאסטר, 320 גרם למ״ר", "מוברש מבפנים", "שרוך עם קצוות זהב מוברש", "שני כיסים צדדיים עמוקים", "רקמת זהב על הרגל השמאלית"]'::jsonb, '/store/images/am-shorts-black.jpg'),
  ('am-shorts-white', 'AM SHORTS — WHITE', 'מכנסי פוטר לבנים', 'shorts', 'לבן', 229, NULL, NULL, 'אותם מכנסיים בלבן, עם קצוות שרוך בזהב מוברש.', 'הגרסה הלבנה. אותו פוטר כבד ואותה גזרה, בלבן שמחזיק את הצורה. השרוך והקצוות בזהב מוברש, והלוגו רקום על הרגל השמאלית.', '["פוטר 80% כותנה, 20% פוליאסטר, 320 גרם למ״ר", "מוברש מבפנים", "שרוך עם קצוות זהב מוברש", "שני כיסים צדדיים עמוקים", "רקמת זהב על הרגל השמאלית"]'::jsonb, '/store/images/am-shorts-white.jpg'),
  ('am-set-black', 'AM SET — BLACK', 'סט שחור מלא', 'sets', 'שחור', 369, 408, 'חיסכון ₪39', 'הטי והמכנסיים בשחור, יחד — במחיר נמוך מרכישה בנפרד.', 'הסט המלא בשחור: חולצת הטי ומכנסי הפוטר, באותה מידה או בשתי מידות שונות לבחירתך. אותם פריטים בדיוק, במחיר נמוך מרכישה בנפרד.', '["כולל חולצת טי ומכנסי פוטר", "אפשר לבחור מידות שונות לכל פריט בהערה בהזמנה", "זהה לפריטים הנמכרים בנפרד", "נשלח באריזת מתנה"]'::jsonb, '/store/images/am-set-black.jpg'),
  ('am-set-white', 'AM SET — WHITE', 'סט לבן מלא', 'sets', 'לבן', 369, 408, 'חיסכון ₪39', 'הטי והמכנסיים בלבן, יחד — במחיר נמוך מרכישה בנפרד.', 'הסט המלא בלבן: חולצת הטי ומכנסי הפוטר. הלוק הנקי ביותר של הקולקציה, ובמחיר נמוך מרכישה בנפרד.', '["כולל חולצת טי ומכנסי פוטר", "אפשר לבחור מידות שונות לכל פריט בהערה בהזמנה", "זהה לפריטים הנמכרים בנפרד", "נשלח באריזת מתנה"]'::jsonb, '/store/images/am-set-white.jpg');
